/** 螺旋迷境子赛季：name 为上游错误文本，展示用 displayName。 */
export interface DnaSeasonRiftSeason {
    id: number
    dnaSeasonId: number
    subSeasonNum: number
    name: string
    startTime: number
    endTime: number
    displayName: string
}

export interface DnaSeasonRiftJump {
    floor: number
    time: number
}

export interface DnaSeasonRiftFloor {
    id: number
    floor: number
    floorType: number
    seasonId: number
    monsterLevel: number
    completeTime: number
    isNodeLayer: number
    dsEnable: boolean
    dungeonIds?: number[]
    bossUnitIds?: number[]
    normalMonsterIds?: number[]
    eliteMonsterIds?: number[]
    challengeIds?: number[]
    passReward?: number
    scoreRuleIds?: number[]
    jumps?: DnaSeasonRiftJump[]
    unlockTierIds?: number[]
}

export interface DnaSeasonRankConfig {
    id: number
    rankType: number
    rankSubType?: number
    capacity: number
    viewCapacity: number
    /** 排行档位名（Solo / Role / Team），1.8.7.1 上游新增 */
    rankTypeName?: string
    /** 服务端排行类型（RiftSoloRank / RiftRoleRank / RiftTeamRank），1.8.7.1 上游新增 */
    serverRankType?: string
    /** 分组字母（A-E），仅 Role 档 */
    groupLetter?: string
    /** 队伍人数，仅 Team 档 */
    teamSize?: number
}

export interface DnaSeasonRankRewardMail {
    title: string
    content: string
    timeLimitDays: number
    ifStar: boolean
}

export interface DnaSeasonRankReward {
    id: number
    subSeasonId: number
    rankType: number
    rankSubType?: number
    rankRange: [number, number]
    rewardType: number
    rewardMailId: number
    rankTypeName?: string
    groupLetter?: string
    /** 奖励周期类型（Period），1.8.7.1 上游新增 */
    rewardTypeName?: string
    mail?: DnaSeasonRankRewardMail
    rewardId?: number
}

export interface DnaSeasonRankRole {
    id: number
    subSeasonId: number
    group: number
    groupLetter?: string
    roleIds: number[]
}

export interface DnaSeasonChallengeDropBonus {
    id: number
    rate: number
}

export interface DnaSeasonChallenge {
    id: number
    type: number
    title: string
    detailTitle: string
    detailDesc: string
    icon: string
    param1: number
    dropBonus: DnaSeasonChallengeDropBonus[]
}

export interface DnaSeasonMonsterScore {
    id: number
    enableKillScore: boolean
    normal: number
    elite: number
    strong: number
    advanced: number
    segmentScoreThreshold: number
    totalScoreThreshold: number
}

export interface DnaSeasonRiftGlobals {
    RiftInitUnlockLayer: number
    RiftMaxLayer: number
    RiftRankDeathInitialPenalty: number
    RiftRankDeathPenalty: number
    RiftRankRewardTime: number
    RiftReviveCountdown: number
}

